from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" a , 3 , 1 \n", "b, -2, 0", " c,4, \t"]) == [
        {"id": "a", "day": 3, "converted": True},
        {"id": "b", "day": -2, "converted": False},
        {"id": "c", "day": 4, "converted": None},
    ]


def test_parse_session_log_skips_blank_whitespace_and_comment_lines():
    lines = ["", "\n", " \t\n", "# comment", " \t# another comment", "a,1,0"]
    assert parse_session_log(lines) == [{"id": "a", "day": 1, "converted": False}]
    assert parse_session_log(lines[:-1]) == []
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_session_log_error_contains_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["# comment", "", "a,1,1", " \t", bad_line])
    with pytest.raises(ValueError, match=r"\bline 1\b"):
        parse_session_log([bad_line])


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    original = {"id": "b", "day": 9, "converted": True}
    replacement = {"id": "b", "day": 2, "converted": None}
    a = {"id": "a", "day": 2, "converted": False}
    z = {"id": "z", "day": 1, "converted": True}
    events = [original, a, z, replacement]
    assert dedupe_sessions(events) == [z, a, replacement]
    assert events == [original, a, z, replacement]


def test_dedupe_sessions_empty():
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_gaps():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": False},
        {"day": 2, "converted": None},
        {"day": 4, "converted": True},
        {"day": 5, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 4, 1) == []


def test_daily_conversion_counts_no_sessions():
    assert daily_conversion_counts([], -1, 2) == [0, 0, 0, 0]
    assert daily_conversion_counts([], 2, 1) == []
